export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly concurrency: number;
  private readonly maxRetries: number;
  private readonly pending: Array<() => Promise<void>> = [];
  private idleWaiters: Array<() => void> = [];
  private active = 0;

  constructor(concurrency: number, maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    if (!Number.isInteger(maxRetries) || maxRetries < 0) {
      throw new RangeError("maxRetries must be a non-negative integer");
    }
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
  }

  /** Number of jobs waiting or running. */
  get size(): number {
    return this.pending.length + this.active;
  }

  /**
   * Enqueue a job. Resolves with the job's result, or rejects with its last
   * error once every retry has failed.
   */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.runWithRetries(job).then(resolve, reject));
      this.drain();
    });
  }

  /** Resolves once nothing is waiting or running, including jobs added later. */
  onIdle(): Promise<void> {
    if (this.size === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  // A retrying job keeps its concurrency slot until it succeeds or gives up.
  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let failures = 0; ; failures++) {
      try {
        return await job();
      } catch (err) {
        if (failures >= this.maxRetries) throw err;
      }
    }
  }

  private drain(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.active++;
      void run().finally(() => {
        this.active--;
        this.drain();
      });
    }
    if (this.size === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { JobQueue } from "./jobQueue.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

test("respects concurrency limit", async () => {
  const queue = new JobQueue(2);
  let running = 0;
  let peak = 0;
  for (let i = 0; i < 10; i++) {
    void queue.add(async () => {
      peak = Math.max(peak, ++running);
      await sleep(5);
      running--;
    });
  }
  await queue.onIdle();
  assert.equal(peak, 2);
  assert.equal(queue.size, 0);
});

test("retries until success", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const result = await queue.add(async () => {
    if (++calls < 4) throw new Error("fail");
    return "ok";
  });
  assert.equal(result, "ok");
  assert.equal(calls, 4);
});

test("rejects after three retries", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const failed = queue.add(async () => {
    calls++;
    throw new Error(`fail ${calls}`);
  });
  await assert.rejects(failed, /fail 4/);
  assert.equal(calls, 4);
});

test("retries a job that throws synchronously", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const failed = queue.add(() => {
    calls++;
    throw new Error("sync");
  });
  await assert.rejects(failed, /sync/);
  assert.equal(calls, 4);
});

test("onIdle waits for failing jobs and resolves at once when empty", async () => {
  const queue = new JobQueue(3);
  await queue.onIdle();
  let done = 0;
  for (let i = 0; i < 5; i++) {
    queue
      .add(async () => {
        await sleep(2);
        if (i % 2) throw new Error("odd");
      })
      .catch(() => {})
      .finally(() => done++);
  }
  await queue.onIdle();
  await sleep(0);
  assert.equal(done, 5);
});

